188	impl PypiRegistry {
189	    /// One `curl` of the project's simple index; `Err` when the command could not run at all.
190	    fn fetch_once(
191	        context: &ProviderContext<'_>,
192	        operation: &RegistryPublishOperation,
193	    ) -> Result<Result<CommandOutput, policy::CommandUnavailable>, GraphError> {
194	        let url = pypi_simple_index_url(operation.registry.endpoint.as_deref(), &operation.package_name);
195	        let accept_header = format!("Accept: {PYPI_SIMPLE_ACCEPT}");
196	        let args = ["-sS", "-i", "-H", accept_header.as_str(), url.as_str()];
197	        run_observation(
198	            context.runner(),
199	            programs::CURL,
200	            &args,
201	            context.root(),
202	            timeouts::REGISTRY_QUERY,
203	            false,
204	        )
205	    }
206	
207	    /// The release's files on the index, retried on a transient failure.
208	    fn remote(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<PypiRemote, GraphError> {
209	        policy::retry_observation(context.sleeper(), || {
210	            Ok(match Self::fetch_once(context, operation)? {
211	                Ok(output) => classify_pypi_files(&output, &operation.version),
212	                Err(_unavailable) => Attempt::Transient {
213	                    value: PypiRemote::Indeterminate(ProviderIndeterminateCause::CommandFailed),
214	                    retry_after: None,
215	                },
216	            })
217	        })
218	    }
219	
220	    /// The files of this release, once per run: the build job's sealed set when the manifest has one, else a build.
221	    fn built_set(
222	        context: &ProviderContext<'_>,
223	        id: &ReleaseOperationId,
224	        operation: &RegistryPublishOperation,
225	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
226	    ) -> Result<Arc<BuiltSet>, GraphError> {
227	        let sets = context.file_sets().ok_or_else(|| GraphError::ReleaseInvariant {
228	            detail: "a Python release needs the per-run file set cache".to_string(),
229	        })?;
230	        sets.get_or_build(
231	            (operation.package_dir.clone(), operation.version.render().to_string()),
232	            || match artifacts.and_then(|artifacts| artifacts.sealed_files(&id.package, &operation.version)) {
233	                Some(files) => BuiltSet::sealed(
234	                    files
235	                        .into_iter()
236	                        .map(|file| BuiltFile {
237	                            filename: file.filename,
238	                            path: file.path,
239	                            sha256: file.sha256,
240	                        })
241	                        .collect(),
242	                    &operation.package_name,
243	                    &operation.version,
244	                ),
245	                None => {
246	                    if artifacts.is_some() {
247	                        eprintln!(
248	                            "warning: the artifact manifest does not seal {} {}; building it in this job",
249	                            operation.package_name,
250	                            operation.version.render()
251	                        );
252	                    }
253	                    Self::build_set(context, operation)
254	                }
255	            },
256	        )
257	    }
258	
259	    /// Builds the sdist and wheel into a fresh directory, so a stale `dist/` can never reach the upload.
260	    fn build_set(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<BuiltSet, GraphError> {
261	        let dir = tempfile::tempdir().map_err(|error| {
262	            GraphError::Command(callisto_model::CommandError::Io {
263	                program: "python -m build".to_string(),
264	                message: error.to_string(),
265	            })
266	        })?;
267	        Self::build_into(context, operation, dir.path())?;
268	        BuiltSet::from_dir(dir, &operation.package_name, &operation.version)
269	    }
270	
271	    /// Runs the build into `outdir`, with file timestamps pinned to the release commit.
272	    pub(crate) fn build_into(
273	        context: &ProviderContext<'_>,
274	        operation: &RegistryPublishOperation,
275	        outdir: &std::path::Path,
276	    ) -> Result<(), GraphError> {
277	        let epoch = callisto_model::vcs::GitAccess::new(context.root(), context.runner()).commit_time("HEAD")?;
278	        let build = registry_argv::pypi_build_argv(context.root(), &operation.package_dir, outdir, epoch)?;
279	        let built = run_build_argv(context, &build)?;
280	        if built.exit_code != Some(0) {
281	            return Err(GraphError::ReleaseCommand {
282	                program: build.program.clone(),
283	                args: build.args.clone(),
284	                failure: CommandFailure::NonZeroExit {
285	                    exit_code: built.exit_code,
286	                    stderr: built.stderr,
287	                },
288	            });
289	        }
290	        Ok(())
291	    }
292	}
293	
294	/// Files on the index that no build of this release declared are never checked, but they are worth a line.
295	pub(super) fn warn_about_extra_files(operation: &RegistryPublishOperation, extras: &[&str]) {
296	    if !extras.is_empty() {
297	        eprintln!(
298	            "warning: the index lists {} for {} {}, which this release did not build; it is not checked",
299	            extras.join(", "),
300	            operation.package_name,
301	            operation.version.render()
302	        );
303	    }
304	}
305	
306	impl RegistryEcosystem for PypiRegistry {
307	    fn ecosystem(&self) -> Ecosystem {
308	        Ecosystem::Pypi
309	    }
310	
311	    /// PyPI's own JSON simple index (PEP 691) answers exactly like every
312	    /// other registry: 200 with the version present or absent, 404 for an
313	    /// unknown project. `pip` cannot observe this; `curl` against the index
314	    /// directly can.
315	    fn can_observe_versions(&self) -> bool {
316	        true
317	    }
318	
319	    fn observe_once(
320	        &self,
321	        context: &ProviderContext<'_>,
322	        operation: &RegistryPublishOperation,
323	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
324	        let output = match Self::fetch_once(context, operation)? {
325	            Ok(output) => output,
326	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
327	        };
328	        Ok(classify_pypi_simple(&output, &operation.version))
329	    }
330	
331	    /// No file on the index needs no build; any file means a partial release, so a build says which are missing.
332	    fn preflight(
333	        &self,
334	        context: &ProviderContext<'_>,
335	        id: &ReleaseOperationId,
336	        operation: &RegistryPublishOperation,
337	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
338	    ) -> Result<ReleasePreflight, GraphError> {
339	        let remote = match Self::remote(context, operation)? {
340	            PypiRemote::Absent => return Ok(proceed()),
341	            PypiRemote::Indeterminate(cause) => {
342	                return Err(GraphError::ReleaseProviderIndeterminate {
343	                    operation: Box::new(id.clone()),
344	                    cause,
345	                })
346	            }
347	            PypiRemote::Files(remote) => remote,
348	        };
349	        let set = Self::built_set(context, id, operation, artifacts)?;
350	        let comparison = pypi_files::compare(&set, &remote);
351	        warn_about_extra_files(operation, &comparison.extras);
352	        if let Some(filename) = comparison.differing.first() {
353	            return Err(GraphError::PypiFileDiffers {
354	                filename: (*filename).to_string(),
355	            });
356	        }
357	        if !comparison.yanked.is_empty() {
358	            return preflight_from_observation(
359	                ProviderObservationV1::Conflict {
360	                    reason: ProviderConflictReason::RegistryVersionYanked,
361	                },
362	                id,
363	                RemoteConflict::RegistryVersionDiffers,
364	            );
365	        }
366	        if comparison.is_complete() {
367	            return preflight_from_observation(
368	                exact_version(&operation.version),
369	                id,
370	                RemoteConflict::RegistryVersionDiffers,
371	            );
372	        }
373	        Ok(proceed())
374	    }
375	
376	    /// Uploads only the files the index lacks, named one by one: a file already there is never offered again.
377	    fn publish(
378	        &self,
379	        context: &ProviderContext<'_>,
380	        id: &ReleaseOperationId,
381	        operation: &RegistryPublishOperation,
382	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
383	    ) -> Result<CommandOutput, GraphError> {
384	        let set = Self::built_set(context, id, operation, artifacts)?;
385	        let remote = match Self::remote(context, operation)? {
386	            PypiRemote::Absent => Vec::new(),
387	            PypiRemote::Files(remote) => remote,
388	            PypiRemote::Indeterminate(cause) => {
389	                return Err(GraphError::ReleaseProviderIndeterminate {
390	                    operation: Box::new(id.clone()),
391	                    cause,
392	                })
393	            }
394	        };
395	        let comparison = pypi_files::compare(&set, &remote);
396	        if let Some(filename) = comparison.differing.first() {
397	            return Err(GraphError::PypiFileDiffers {
398	                filename: (*filename).to_string(),
399	            });
400	        }
401	        if !comparison.yanked.is_empty() {
402	            return Err(GraphError::ReleaseRemoteConflict {
403	                conflict: RemoteConflict::RegistryVersionDiffers,
404	            });
405	        }
406	        let missing: Vec<&BuiltFile> = set
407	            .files
408	            .iter()
409	            .filter(|file| comparison.missing.contains(&file.filename.as_str()))
410	            .collect();
411	        if missing.is_empty() {
412	            return Ok(CommandOutput {
413	                exit_code: Some(0),
414	                stdout: String::new(),
415	                stderr: String::new(),
416	            });
417	        }
418	        set.recheck(&missing)?;
419	        let paths: Vec<_> = missing.iter().map(|file| file.path.clone()).collect();
420	        let upload = registry_argv::pypi_upload_argv(
421	            context.root(),
422	            &operation.package_dir,
423	            operation.registry.upload_endpoint(),
424	            &paths,
425	        );
426	        let output = run_pypi_upload_argv(context, &upload, publish_timeout(operation))?;
427	        if output.success() {
428	            set.mark_uploaded(&missing);
429	        }
430	        Ok(output)
431	    }
432	
433	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
434	        registry_argv::classify_twine_output(output)
435	    }
436	
437	    /// Waits for every file to be on the index; a sealed or uploaded file must carry the bytes it was sealed or sent with.
438	    fn confirm(
439	        &self,
440	        context: &ProviderContext<'_>,
441	        id: &ReleaseOperationId,
442	        operation: &RegistryPublishOperation,
443	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
444	    ) -> Result<ProviderObservationV1, GraphError> {
445	        let set = Self::built_set(context, id, operation, artifacts)?;
446	        let observe = || -> Result<ProviderObservationV1, GraphError> {
447	            Ok(match Self::remote(context, operation)? {
448	                PypiRemote::Indeterminate(cause) => ProviderObservationV1::Indeterminate { cause },
449	                PypiRemote::Absent => ProviderObservationV1::Absent,
450	                PypiRemote::Files(remote) => {
451	                    let comparison = pypi_files::compare(&set, &remote);
452	                    if !comparison.yanked.is_empty() {
453	                        ProviderObservationV1::Conflict {
454	                            reason: ProviderConflictReason::RegistryVersionYanked,
455	                        }
456	                    } else if let Some(filename) = comparison.differing.first() {
457	                        return Err(GraphError::PypiFileDiffers {
458	                            filename: (*filename).to_string(),
459	                        });
460	                    } else if comparison.missing.is_empty() {
461	                        exact_version(&operation.version)
462	                    } else {
463	                        ProviderObservationV1::Absent
464	                    }
465	                }
466	            })
467	        };
468	        policy::observe_within_window(context.sleeper(), visibility_window(self, operation), observe)
469	    }
470	}
