90	/// Retries `attempt` while it reports `Transient`, until `window` of waiting is spent; the last answer is then reported.
91	///
92	/// Unlike [`retry_observation`] the bound is time, not tries: how long a registry lags is a property of the registry,
93	/// not of how many times it was asked.
94	pub(crate) fn retry_within_window<T>(
95	    sleeper: &dyn Sleeper,
96	    window: Duration,
97	    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
98	) -> Result<T, GraphError> {
99	    let mut waited = Duration::ZERO;
100	    let mut index = 0;
101	    loop {
102	        match attempt()? {
103	            Attempt::Settled(value) => return Ok(value),
104	            Attempt::Transient { value, retry_after } => {
105	                let remaining = window.saturating_sub(waited);
106	                if remaining.is_zero() {
107	                    return Ok(value);
108	                }
109	                let wait = retry_after
110	                    .unwrap_or_else(|| visibility_backoff(index))
111	                    .clamp(Duration::from_secs(1), OBSERVATION_BACKOFF_CAP)
112	                    .min(remaining);
113	                sleeper.sleep(wait);
114	                waited += wait;
115	                index += 1;
116	            }
117	        }
118	    }
119	}
120	
121	/// Re-observes this run's own publish while the registry reads `Absent` or cannot be asked, for up to `window`; any
122	/// other answer is final.
123	pub(crate) fn observe_within_window(
124	    sleeper: &dyn Sleeper,
125	    window: Duration,
126	    mut observe: impl FnMut() -> Result<ProviderObservationV1, GraphError>,
127	) -> Result<ProviderObservationV1, GraphError> {
128	    retry_within_window(sleeper, window, || {
129	        let observation = observe()?;
130	        Ok(match observation {
131	            ProviderObservationV1::Absent | ProviderObservationV1::Indeterminate { .. } => Attempt::Transient {
132	                value: observation,
133	                retry_after: None,
134	            },
135	            settled => Attempt::Settled(settled),
136	        })
137	    })
138	}
139	
140	/// GitHub's reads lag its writes by seconds; waits of 2s to 32s cover about a minute.
141	pub(crate) const EFFECT_VISIBILITY_ATTEMPTS: u32 = 6;
142	
143	/// Re-observes this run's own effect while it reads `Absent`; any other answer is final.
144	pub(crate) fn observe_until_visible(
145	    sleeper: &dyn Sleeper,
146	    mut observe: impl FnMut() -> Result<ProviderObservationV1, GraphError>,
147	) -> Result<ProviderObservationV1, GraphError> {
148	    let mut index = 0;
149	    loop {
150	        let observation = observe()?;
151	        if !matches!(observation, ProviderObservationV1::Absent) || index + 1 >= EFFECT_VISIBILITY_ATTEMPTS {
152	            return Ok(observation);
153	        }
154	        sleeper.sleep(observation_backoff(index));
155	        index += 1;
156	    }
157	}
