159	/// One attempt's result: either it settled the question, or it left the answer
160	/// unknown for a reason that may resolve on its own.
161	#[derive(Debug, PartialEq, Eq)]
162	pub(crate) enum Attempt<T> {
163	    Settled(T),
164	    /// `value` is the answer to report if every attempt is exhausted.
165	    Transient {
166	        value: T,
167	        retry_after: Option<Duration>,
168	    },
169	}
170	
171	/// The wall-clock wait, injected so tests exercise the schedule without it.
172	pub(crate) trait Sleeper: Sync {
173	    fn sleep(&self, duration: Duration);
174	}
175	
176	pub(crate) struct ThreadSleeper;
177	
178	impl Sleeper for ThreadSleeper {
179	    fn sleep(&self, duration: Duration) {
180	        std::thread::sleep(scaled_for_tests(duration));
181	    }
182	}
