184	/// Test-only, like cargo's `__CARGO_TEST_*`: e2e tests can't inject a `Sleeper`.
185	fn scaled_for_tests(duration: Duration) -> Duration {
186	    match std::env::var("__CALLISTO_TEST_SLEEP_SCALE") {
187	        Ok(raw) => match raw.parse::<f64>() {
188	            Ok(scale) if scale.is_finite() && scale >= 0.0 => duration.mul_f64(scale),
189	            _ => duration,
190	        },
191	        Err(_) => duration,
192	    }
193	}
194	
195	/// A command that could not be run at all (timed out or failed to spawn), unlike one that ran and exited non-zero.
196	#[derive(Debug)]
197	pub(crate) struct CommandUnavailable;
198	
199	/// Translates a timeout or I/O failure into `CommandUnavailable` so `retry_observation` can retry it, instead
200	/// of propagating a hard `GraphError`. `NotFound` stays a hard error: retrying can't install a missing program.
201	pub(crate) fn run_observation(
202	    runner: &dyn CommandRunner,
203	    program: &str,
204	    args: &[&str],
205	    cwd: &Path,
206	    timeout: Duration,
207	    quiet: bool,
208	) -> Result<Result<CommandOutput, CommandUnavailable>, GraphError> {
209	    let result = if quiet {
210	        runner.run_quiet(program, args, cwd, timeout)
211	    } else {
212	        runner.run_with_timeout(program, args, cwd, timeout)
213	    };
214	    match result {
215	        Ok(output) => Ok(Ok(output)),
216	        Err(CommandError::TimedOut { .. } | CommandError::Io { .. }) => Ok(Err(CommandUnavailable)),
217	        Err(other) => Err(other.into()),
218	    }
219	}
