221	/// The one bounded retry in the release path. It wraps read-only observations
222	/// only: an effect (publish, push, release create, asset upload) is never
223	/// re-issued from here, because a transient error cannot prove the first
224	/// attempt did not take effect.
225	pub(crate) fn retry_observation<T>(
226	    sleeper: &dyn Sleeper,
227	    attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
228	) -> Result<T, GraphError> {
229	    retry_observation_within(sleeper, None, attempt)
230	}
231	
232	/// [`retry_observation`] that stops retrying once `patience` of waiting is spent, and reports the last answer. A
233	/// caller that is itself waiting out a window gives its look the window that is left, so a registry that asks for
234	/// long waits cannot hold the look past it.
235	pub(crate) fn retry_observation_within<T>(
236	    sleeper: &dyn Sleeper,
237	    patience: Option<Duration>,
238	    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
239	) -> Result<T, GraphError> {
240	    let mut exhausted = None;
241	    let mut waited = Duration::ZERO;
242	    for index in 0..OBSERVATION_MAX_ATTEMPTS {
243	        match attempt()? {
244	            Attempt::Settled(value) => return Ok(value),
245	            Attempt::Transient { value, retry_after } => {
246	                exhausted = Some(value);
247	                if index + 1 < OBSERVATION_MAX_ATTEMPTS {
248	                    let wait = retry_after
249	                        .unwrap_or_else(|| observation_backoff(index))
250	                        .min(OBSERVATION_BACKOFF_CAP);
251	                    let wait = patience.map_or(wait, |patience| wait.min(patience.saturating_sub(waited)));
252	                    if wait.is_zero() && patience.is_some() {
253	                        break;
254	                    }
255	                    sleeper.sleep(wait);
256	                    waited += wait;
257	                }
258	            }
259	        }
260	    }
261	    Ok(exhausted.expect("at least one attempt always runs"))
262	}
263	
264	/// A successful publish-client exit isn't a receipt: confirms the registry
265	/// itself has caught up before treating the operation as done. If not, it
266	/// stays `Attempting` for reconciliation, reported via its own variant
267	/// rather than `ReleaseIntentStale`'s false "no operation was authorized".
268	pub(crate) fn require_registry_confirmation(
269	    is_published: bool,
270	    package: &str,
271	    version: &Version,
272	    waited: Duration,
273	) -> Result<(), GraphError> {
274	    if is_published {
