1	//! The Python release flow against a fake index, build and twine: a release is complete only when every file the
2	//! build declares is on the index, and a rerun uploads only what is missing.
3	
4	use std::path::{Path, PathBuf};
5	use std::sync::Mutex;
6	
7	use callisto_model::{
8	    CommandError, CommandOutput, CommandRunner, RegistryBindingDigest, RegistryBindingId, RegistryKey,
9	    ReleaseOperationId, ReleasePackageId, Version, VersionGrammar,
10	};
11	use sha2::{Digest, Sha256};
12	
13	use super::super::policy::tests::RecordingSleeper;
14	use super::super::PypiFileSets;
15	use super::*;
16	use crate::commands::release::binding::PreparedRegistryBinding;
17	
18	const WHEEL: &str = "my_pkg-1.0.0-py3-none-any.whl";
19	const SDIST: &str = "my_pkg-1.0.0.tar.gz";
20	
21	fn sha256(content: &str) -> String {
22	    Sha256::digest(content.as_bytes())
23	        .iter()
24	        .map(|byte| format!("{byte:02x}"))
25	        .collect::<String>()
26	}
27	
28	/// One file on the fake index.
29	#[derive(Clone)]
30	struct Held {
31	    filename: String,
32	    sha256: String,
33	    yanked: bool,
34	}
35	
36	#[derive(Default)]
37	struct World {
38	    /// Files the index serves now.
39	    visible: Vec<Held>,
40	    /// Uploaded files the index shows after `lag` more reads.
41	    pending: Vec<Held>,
42	    lag: usize,
43	    /// What `python -m build` writes: filename and content.
44	    build_output: Vec<(String, String)>,
45	    /// Uploads that fail after this many files, with an HTTP error.
46	    fail_upload_after: Option<usize>,
47	    /// Uploads whose stored digest differs from the sent bytes.
48	    corrupt_uploads: bool,
49	    calls: Vec<String>,
50	    uploads: Vec<Vec<String>>,
51	    /// The `SOURCE_DATE_EPOCH` each build ran with.
52	    epochs: Vec<String>,
53	}
54	
55	struct PypiRunner(Mutex<World>);
56	
57	impl PypiRunner {
58	    fn new(build: &[(&str, &str)]) -> Self {
59	        Self(Mutex::new(World {
60	            build_output: build.iter().map(|(n, c)| (n.to_string(), c.to_string())).collect(),
61	            ..World::default()
62	        }))
63	    }
64	
65	    fn with(self, edit: impl FnOnce(&mut World)) -> Self {
66	        edit(&mut self.0.lock().unwrap());
67	        self
68	    }
69	
70	    fn count(&self, program: &str) -> usize {
71	        let world = self.0.lock().unwrap();
72	        world
73	            .calls
74	            .iter()
75	            .filter(|call| call.split(' ').next() == Some(program))
76	            .count()
77	    }
78	
79	    fn calls(&self, program: &str) -> Vec<String> {
80	        let world = self.0.lock().unwrap();
81	        world
82	            .calls
83	            .iter()
84	            .filter(|call| call.split(' ').next() == Some(program))
85	            .cloned()
86	            .collect()
87	    }
88	
89	    fn epochs(&self) -> Vec<String> {
90	        self.0.lock().unwrap().epochs.clone()
91	    }
92	
93	    fn uploads(&self) -> Vec<Vec<String>> {
94	        self.0.lock().unwrap().uploads.clone()
95	    }
96	
97	    /// The index shows every upload that has reached it.
98	    fn settle(&self) {
99	        let mut world = self.0.lock().unwrap();
100	        let arrived = std::mem::take(&mut world.pending);
101	        world.visible.extend(arrived);
102	    }
103	
104	    fn held(&self) -> Vec<String> {
105	        let world = self.0.lock().unwrap();
106	        world.visible.iter().map(|file| file.filename.clone()).collect()
107	    }
108	}
109	
110	fn ok(stdout: &str) -> Result<CommandOutput, CommandError> {
111	    Ok(CommandOutput {
112	        exit_code: Some(0),
113	        stdout: stdout.to_string(),
114	        stderr: String::new(),
115	    })
116	}
117	
118	impl PypiRunner {
119	    fn handle(&self, program: &str, args: &[&str]) -> Result<CommandOutput, CommandError> {
120	        if program == "env" {
121	            let epoch = args[0]
122	                .strip_prefix("SOURCE_DATE_EPOCH=")
123	                .expect("the build pins its timestamps");
124	            self.0.lock().unwrap().epochs.push(epoch.to_string());
125	            return self.handle(args[1], &args[2..]);
126	        }
127	        let mut world = self.0.lock().unwrap();
128	        world.calls.push(format!("{program} {}", args.join(" ")));
129	        match program {
130	            "git" => ok("1700000000\n"),
131	            "curl" => {
132	                if world.lag > 0 {
133	                    world.lag -= 1;
134	                } else {
135	                    let arrived = std::mem::take(&mut world.pending);
136	                    world.visible.extend(arrived);
137	                }
138	                if world.visible.is_empty() {
139	                    return ok("HTTP/2 404 Not Found\r\n\r\n");
140	                }
141	                let files: Vec<serde_json::Value> = world
142	                    .visible
143	                    .iter()
144	                    .map(|file| {
145	                        serde_json::json!({
146	                            "filename": file.filename,
147	                            "url": "https://files.example.invalid/x",
148	                            "hashes": if file.sha256.is_empty() {
149	                                serde_json::json!({})
150	                            } else {
151	                                serde_json::json!({ "sha256": file.sha256 })
152	                            },
153	                            "yanked": file.yanked,
154	                        })
155	                    })
156	                    .collect();
157	                let body = serde_json::json!({ "meta": { "api-version": "1.0" }, "name": "my-pkg", "files": files });
158	                ok(&format!(
159	                    "HTTP/2 200 OK\r\ncontent-type: application/vnd.pypi.simple.v1+json\r\n\r\n{body}"
160	                ))
161	            }
162	            "python3" | "python" => {
163	                let outdir = PathBuf::from(args[args.iter().position(|arg| *arg == "--outdir").unwrap() + 1]);
164	                for (name, content) in &world.build_output {
165	                    std::fs::write(outdir.join(name), content).unwrap();
166	                }
167	                ok("")
168	            }
169	            "twine" => {
170	                let files: Vec<String> = args
171	                    .iter()
172	                    .skip(1)
173	                    .filter(|arg| !arg.starts_with("--") && !arg.starts_with("http"))
174	                    .map(|arg| arg.to_string())
175	                    .collect();
176	                world.uploads.push(
177	                    files
178	                        .iter()
179	                        .map(|file| Path::new(file).file_name().unwrap().to_string_lossy().into_owned())
180	                        .collect(),
181	                );
182	                for (sent, file) in files.iter().enumerate() {
183	                    if world.fail_upload_after == Some(sent) {
184	                        return Ok(CommandOutput {
185	                            exit_code: Some(1),
186	                            stdout: String::new(),
187	                            stderr: "HTTPError: 503 Service Unavailable".to_string(),
188	                        });
189	                    }
190	                    let bytes = std::fs::read_to_string(file).unwrap();
191	                    let digest = if world.corrupt_uploads {
192	                        "0".repeat(64)
193	                    } else {
194	                        sha256(&bytes)
195	                    };
196	                    let held = Held {
197	                        filename: Path::new(file).file_name().unwrap().to_string_lossy().into_owned(),
198	                        sha256: digest,
199	                        yanked: false,
200	                    };
201	                    world.pending.push(held);
202	                }
203	                ok("Uploading\n")
204	            }
205	            other => panic!("unexpected program {other}"),
206	        }
207	    }
208	}
209	
210	impl CommandRunner for PypiRunner {
211	    fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
212	        self.handle(program, args)
213	    }
214	
215	    fn run_with_timeout_env_filtered(
216	        &self,
217	        program: &str,
218	        args: &[&str],
219	        _cwd: &Path,
220	        _timeout: std::time::Duration,
221	        _removed: &[&str],
222	    ) -> Result<CommandOutput, CommandError> {
223	        self.handle(program, args)
224	    }
225	
226	    fn run_with_timeout_publisher(
227	        &self,
228	        program: &str,
229	        args: &[&str],
230	        _cwd: &Path,
231	        _timeout: std::time::Duration,
232	        _env: &[(&str, &str)],
233	    ) -> Result<CommandOutput, CommandError> {
234	        self.handle(program, args)
235	    }
236	}
